/*!40101 SET NAMES utf8 */;

create table `creature` (
	`guid` int (10),
	`id` int (10),
	`map` smallint (5),
	`zoneId` smallint (5),
	`areaId` smallint (5),
	`spawnMask` tinyint (3),
	`phaseMask` int (10),
	`equipment_id` tinyint (4),
	`position_x` float ,
	`position_y` float ,
	`position_z` float ,
	`orientation` float ,
	`spawntimesecs` int (10),
	`wander_distance` float ,
	`currentwaypoint` int (10),
	`curhealth` int (10),
	`curmana` int (10),
	`MovementType` tinyint (3),
	`npcflag` int (10),
	`unit_flags` int (10),
	`dynamicflags` int (10),
	`ScriptName` char (192),
	`VerifiedBuild` int (11),
	`CreateObject` tinyint (3),
	`Comment` text 
); 
